                  "low",
                  "medium",
                  "high"
                ],
                "description": "Severity."
              },
              "note": {
                "type": "string",
                "description": "One sentence on the exposure."
              }
            },
            "required": [
              "severity",
              "note"
            ],
            "additionalProperties": false
          }
        },
        "required": [
          "clause",
          "section",
          "counterparty_tier",
          "proposed_action",
          "playbook_position_id",
          "risk_flag"
        ],
        "additionalProperties": false
      },
      "description": "One entry per playbook clause."
    },
