    "counsel_notes",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Contract agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize contract event'); // one(): defined by guardPreamble; survives a lost item link
const fingerprint = (o) => {
  const canon = (v) => Array.isArray(v) ? '[' + v.map(canon).join(',') + ']'
    : v && typeof v === 'object' ? '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canon(v[k])).join(',') + '}'
    : JSON.stringify(v ?? null);
  const s = canon(o);
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
};
const redlineOf = (agreementId, baseVersionId, baseSha, edits) => ({
  agreement_id: agreementId, base_version_id: baseVersionId, base_sha256: baseSha,
  edits: (edits ?? []).map((e) => ({ clause: e.clause, section: e.section, playbook_position_id: e.playbook_position_id })),
});
const ag = $json; // fresh read: agreement status, current version, playbook for its type
const current = ag.current_version ?? {};
const playbook = ag.playbook?.clauses ?? [];
const byKey = Object.fromEntries(playbook.map((c) => [c.clause, c]));
const review = out?.clause_review ?? [];
const rank = { low: 1, medium: 2, high: 3 };

if (!(cfg.reviewable_statuses ?? []).includes(ag.status)) reasons.push('agreement status is ' + ag.status + ', not open for a redline');
if (current.version_id !== req.version_id) reasons.push('current version is ' + current.version_id + ', this run was for ' + req.version_id);
if (out && out.version_id_reviewed !== current.version_id) reasons.push('agent reviewed version ' + out.version_id_reviewed + ', current version is ' + current.version_id);
if (!current.sha256) reasons.push('current version has no document hash to pin the redline to');
if (!playbook.length) reasons.push('no playbook returned for contract type ' + req.contract_type);

const seen = new Set();
const edits = [];
const flags = [];
for (const c of review) {
  const pb = byKey[c.clause];
  if (!pb) { reasons.push('clause ' + c.clause + ' is not in the playbook'); continue; }
  if (seen.has(c.clause)) reasons.push('clause ' + c.clause + ' reviewed twice');
  seen.add(c.clause);

  // Walk-away territory is counsel's negotiation, never a drafted position.
  if (c.counterparty_tier === 'outside_walk_away') { reasons.push(c.clause + ': counterparty position is outside the playbook walk-away'); continue; }

  let finalTier = c.counterparty_tier;
  if (c.proposed_action === 'accept') {
    if (c.playbook_position_id) reasons.push(c.clause + ': accepted clause should not carry a playbook position id');
  } else {
    const want = c.proposed_action === 'replace_with_preferred' ? pb.preferred_id : pb.fallback_id;
    finalTier = c.proposed_action === 'replace_with_preferred' ? 'preferred' : 'fallback';
    if (!want) reasons.push(c.clause + ': playbook has no ' + finalTier + ' position');
    else if (c.playbook_position_id !== want) reasons.push(c.clause + ': position ' + c.playbook_position_id + ' is not the playbook ' + finalTier + ' position ' + want);
    edits.push({ clause: c.clause, section: c.section, playbook_position_id: c.playbook_position_id, tier: finalTier });
  }

  // Every departure from the preferred position carries a risk flag of the right weight.
  if (finalTier !== 'preferred') {
    const need = finalTier === 'fallback' ? 'medium' : 'high';
    if (!c.risk_flag || !String(c.risk_flag.note ?? '').trim()) reasons.push(c.clause + ': departs from the playbook (' + finalTier + ') without a risk flag');
    else if (rank[c.risk_flag.severity] < rank[need]) reasons.push(c.clause + ': ' + finalTier + ' flagged ' + c.risk_flag.severity + ', needs at least ' + need);
    else flags.push({ clause: c.clause, tier: finalTier, severity: c.risk_flag.severity });
  }
}
for (const pb of playbook) if (!seen.has(pb.clause)) reasons.push('playbook clause ' + pb.clause + ' was not reviewed');

const noop = edits.length === 0 && flags.length === 0;
const redline = redlineOf(req.agreement_id, current.version_id, current.sha256, edits);
const action = {
  type: 'send_redline',
  agreement_id: req.agreement_id,
  base_version_id: current.version_id ?? null,
  base_sha256: current.sha256 ?? null,
  edits,
  risk_flags: flags,
  fingerprint: fingerprint(redline),
  cover_template_id: cfg.cover_template_id,
};
// Ids, tiers and severities only. Clause text stays in the CLM preview.
const preview = cfg.clm_review_url + '/' + req.agreement_id + '/redline-preview?base=' + action.base_version_id + '&positions=' + edits.map((e) => e.playbook_position_id).join(',');
const summary = 'Agreement ' + req.agreement_id + ' (' + req.contract_type + '), redline on version ' + action.base_version_id + ' · fingerprint ' + action.fingerprint + '\n'
  + edits.length + ' playbook edits, ' + flags.length + ' risk flags: ' + (flags.map((f) => f.clause + ' ' + f.tier + ' (' + f.severity + ')').join(', ') || 'none') + '\n'
  + 'Preview: ' + preview + '\n'
  + 'Approve sends exactly this redline with the standard cover note. If the counterparty uploads a new version first, nothing is sent.';
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const fingerprint = (o) => {
  const canon = (v) => Array.isArray(v) ? '[' + v.map(canon).join(',') + ']'
    : v && typeof v === 'object' ? '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canon(v[k])).join(',') + '}'
    : JSON.stringify(v ?? null);
  const s = canon(o);
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
};
const redlineOf = (agreementId, baseVersionId, baseSha, edits) => ({
  agreement_id: agreementId, base_version_id: baseVersionId, base_sha256: baseSha,
  edits: (edits ?? []).map((e) => ({ clause: e.clause, section: e.section, playbook_position_id: e.playbook_position_id })),
});
// Recompute the fingerprint from what the CLM says it sent, not from what it echoes back.
const sent = fingerprint(redlineOf($json.agreement_id, $json.base_version_id, $json.base_sha256, $json.edits));
const ok = $json.status === 'sent'
  && $json.base_version_id === planned.base_version_id
  && $json.base_sha256 === planned.base_sha256
  && sent === planned.fingerprint
  && $json.cover_template_id === planned.cover_template_id;
const detail = 'CLM shows redline ' + $json.status + ' on version ' + $json.base_version_id + ' with fingerprint ' + sent + ', counsel approved ' + planned.fingerprint + ' on ' + planned.base_version_id;
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize contract event'); } catch (e) {}
try { agent = one('Contract agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'Agreement ' + intake.agreement_id + ' · version ' + intake.version_id + ' · ' + intake.contract_type;
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "contracts counsel",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

